// Package codegen renders the single wire contract into Go, TypeScript, and
// documentation artifacts. The contract in internal/protocol/contract.json is
// the source of truth; every generated file carries a DO NOT EDIT header.
package codegen

import (
	"bytes"
	"encoding/json"
	"fmt"
	"go/format"
	"os"
	"sort"
	"strings"
)

// Contract is the machine-readable wire contract.
type Contract struct {
	ProtocolVersion string        `json:"protocolVersion"`
	Capabilities    []string      `json:"capabilities"`
	Methods         []Method      `json:"methods"`
	Errors          []ErrorCode   `json:"errors"`
	Timeouts        TimeoutConfig `json:"timeouts"`
}

// Method is one JSON-RPC method.
type Method struct {
	Name        string `json:"name"`
	Go          string `json:"go"`
	TS          string `json:"ts"`
	DaemonLocal bool   `json:"daemonLocal,omitempty"`
}

// ErrorCode is one stable JSON-RPC error code.
type ErrorCode struct {
	Go   string `json:"go"`
	TS   string `json:"ts"`
	Code int    `json:"code"`
}

// TimeoutConfig groups methods that share one timeout budget.
type TimeoutConfig struct {
	DefaultMs int            `json:"defaultMs"`
	Groups    []TimeoutGroup `json:"groups"`
}

// TimeoutGroup is one named timeout budget.
type TimeoutGroup struct {
	Go      string   `json:"go"`
	Name    string   `json:"name"`
	Ms      int      `json:"ms"`
	Methods []string `json:"methods"`
}

// Load reads and validates a contract file.
func Load(path string) (Contract, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return Contract{}, err
	}
	var contract Contract
	if err := json.Unmarshal(data, &contract); err != nil {
		return Contract{}, fmt.Errorf("decode contract: %w", err)
	}
	if err := contract.Validate(); err != nil {
		return Contract{}, err
	}
	return contract, nil
}

// Validate rejects duplicate identifiers and empty names.
func (c Contract) Validate() error {
	if c.ProtocolVersion == "" {
		return fmt.Errorf("contract: protocolVersion is required")
	}
	seenMethod := map[string]bool{}
	seenTS := map[string]bool{}
	for _, method := range c.Methods {
		if method.Name == "" || method.Go == "" || method.TS == "" {
			return fmt.Errorf("contract: method %+v is missing name/go/ts", method)
		}
		if seenMethod[method.Name] {
			return fmt.Errorf("contract: duplicate method %q", method.Name)
		}
		if seenTS[method.TS] {
			return fmt.Errorf("contract: duplicate TypeScript method key %q", method.TS)
		}
		seenMethod[method.Name] = true
		seenTS[method.TS] = true
	}
	seenError := map[string]bool{}
	for _, code := range c.Errors {
		if code.Go == "" || code.TS == "" {
			return fmt.Errorf("contract: error %+v is missing go/ts", code)
		}
		if seenError[code.Go] {
			return fmt.Errorf("contract: duplicate error %q", code.Go)
		}
		seenError[code.Go] = true
	}
	if c.Timeouts.DefaultMs <= 0 {
		return fmt.Errorf("contract: timeouts.defaultMs must be positive")
	}
	seenTimeout := map[string]bool{}
	for _, group := range c.Timeouts.Groups {
		if group.Go == "" || group.Ms <= 0 {
			return fmt.Errorf("contract: timeout group %+v is invalid", group)
		}
		if seenTimeout[group.Go] {
			return fmt.Errorf("contract: duplicate timeout group %q", group.Go)
		}
		seenTimeout[group.Go] = true
		for _, method := range group.Methods {
			if !seenMethod[method] {
				return fmt.Errorf("contract: timeout group %q references unknown method %q", group.Go, method)
			}
		}
	}
	return nil
}

func header(comment string) string {
	return "// Code generated by internal/protocol/cmd/protocolgen from contract.json; DO NOT EDIT.\n" + comment + "\n\n"
}

// Go renders internal/protocol/methods_generated.go.
func (c Contract) Go() ([]byte, error) {
	var b bytes.Buffer
	b.WriteString(header("// Package protocol defines the chrome-ctl JSON-RPC wire contract."))
	b.WriteString("package protocol\n\n")
	b.WriteString("import \"time\"\n\n")

	fmt.Fprintf(&b, "// ProtocolVersion is advertised in system.ready.\nconst ProtocolVersion = %q\n\n", c.ProtocolVersion)

	b.WriteString("const (\n")
	for _, method := range c.Methods {
		fmt.Fprintf(&b, "\t%s = %q\n", method.Go, method.Name)
	}
	b.WriteString(")\n\n")

	b.WriteString("const (\n")
	for _, code := range c.Errors {
		fmt.Fprintf(&b, "\t%s = %d\n", code.Go, code.Code)
	}
	b.WriteString(")\n\n")

	b.WriteString("const (\n")
	for _, group := range c.Timeouts.Groups {
		fmt.Fprintf(&b, "\t%s = %d * time.Millisecond\n", group.Go, group.Ms)
	}
	b.WriteString(")\n\n")

	b.WriteString("// Capabilities lists optional behavior the daemon can negotiate.\nvar Capabilities = []string{\n")
	for _, capability := range c.Capabilities {
		fmt.Fprintf(&b, "\t%q,\n", capability)
	}
	b.WriteString("}\n\n")

	b.WriteString("var methodTimeouts = map[string]time.Duration{\n")
	for _, group := range c.Timeouts.Groups {
		for _, method := range group.Methods {
			fmt.Fprintf(&b, "\t%q: %s,\n", method, group.Go)
		}
	}
	b.WriteString("}\n\n")

	fmt.Fprintf(&b, "const DefaultTimeout = %d * time.Millisecond\n\n", c.Timeouts.DefaultMs)

	b.WriteString(`// TimeoutMs returns the wire timeout budget for a method.
func TimeoutMs(method string) int {
	if timeout, ok := methodTimeouts[method]; ok {
		return int(timeout.Milliseconds())
	}
	return int(DefaultTimeout.Milliseconds())
}

// TimeoutFor returns a method's timeout or fallback when it has no override.
func TimeoutFor(method string, fallback time.Duration) time.Duration {
	if timeout, ok := methodTimeouts[method]; ok {
		return timeout
	}
	return fallback
}
`)

	formatted, err := format.Source(b.Bytes())
	if err != nil {
		return nil, fmt.Errorf("format generated Go: %w", err)
	}
	return formatted, nil
}

// TS renders extension/src/shared/protocol.generated.ts.
func (c Contract) TS() ([]byte, error) {
	var b bytes.Buffer
	b.WriteString("// Code generated by internal/protocol/cmd/protocolgen from contract.json; DO NOT EDIT.\n\n")
	fmt.Fprintf(&b, "export const PROTOCOL_VERSION = %q;\n\n", c.ProtocolVersion)

	b.WriteString("export const CAPABILITIES = [\n")
	for _, capability := range c.Capabilities {
		fmt.Fprintf(&b, "  %q,\n", capability)
	}
	b.WriteString("] as const;\n\n")

	b.WriteString("export const Methods = {\n")
	for _, method := range c.Methods {
		fmt.Fprintf(&b, "  %s: %q,\n", method.TS, method.Name)
	}
	b.WriteString("} as const;\n\n")

	b.WriteString("export const ErrorCodes = {\n")
	for _, code := range c.Errors {
		fmt.Fprintf(&b, "  %s: %d,\n", code.TS, code.Code)
	}
	b.WriteString("} as const;\n\n")

	fmt.Fprintf(&b, "export const DEFAULT_RPC_TIMEOUT_MS = %d;\n\n", c.Timeouts.DefaultMs)

	b.WriteString("/** Actions can take minutes (humanized typing); every hop uses this budget. */\n")
	b.WriteString("export function rpcTimeoutMs(method: string): number {\n")
	b.WriteString("  switch (method) {\n")
	for _, group := range c.Timeouts.Groups {
		for _, method := range group.Methods {
			fmt.Fprintf(&b, "    case Methods.%s:\n", tsMethodKey(c.Methods, method))
		}
		fmt.Fprintf(&b, "      return %d;\n", group.Ms)
	}
	b.WriteString("    default:\n      return DEFAULT_RPC_TIMEOUT_MS;\n")
	b.WriteString("  }\n}\n")
	return b.Bytes(), nil
}

func tsMethodKey(methods []Method, name string) string {
	for _, method := range methods {
		if method.Name == name {
			return method.TS
		}
	}
	return "unknown"
}

// Docs renders docs/PROTOCOL_CONTRACT.md.
func (c Contract) Docs() ([]byte, error) {
	var b bytes.Buffer
	b.WriteString("# Generated Wire Contract\n\n")
	b.WriteString("> Generated from `internal/protocol/contract.json`; DO NOT EDIT.\n\n")
	fmt.Fprintf(&b, "**Protocol version:** `%s`\n\n", c.ProtocolVersion)

	b.WriteString("## Capabilities\n\n")
	for _, capability := range c.Capabilities {
		fmt.Fprintf(&b, "- `%s`\n", capability)
	}
	b.WriteString("\n## Methods\n\n| Method | Go constant | TypeScript key | Timeout |\n| :--- | :--- | :--- | ---: |\n")
	for _, method := range c.Methods {
		fmt.Fprintf(&b, "| `%s` | `%s` | `%s` | %d ms |\n", method.Name, method.Go, method.TS, c.timeoutFor(method.Name))
	}

	b.WriteString("\n## Error Codes\n\n| Code | Go constant | TypeScript key |\n| ---: | :--- | :--- |\n")
	input := append([]ErrorCode(nil), c.Errors...)
	sort.Slice(input, func(i, j int) bool { return input[i].Code > input[j].Code })
	for _, code := range input {
		fmt.Fprintf(&b, "| %d | `%s` | `%s` |\n", code.Code, code.Go, code.TS)
	}

	b.WriteString("\n## Timeout Groups\n\n| Group | Budget | Methods |\n| :--- | ---: | :--- |\n")
	for _, group := range c.Timeouts.Groups {
		fmt.Fprintf(&b, "| `%s` | %d ms | %s |\n", group.Go, group.Ms, strings.Join(group.Methods, ", "))
	}
	return b.Bytes(), nil
}

func (c Contract) timeoutFor(method string) int {
	for _, group := range c.Timeouts.Groups {
		for _, candidate := range group.Methods {
			if candidate == method {
				return group.Ms
			}
		}
	}
	return c.Timeouts.DefaultMs
}
